/*
 * node_modules/mochiworker_threads — node:worker_threads shim over the
 * engine's own Worker.
 *
 * mbjs:os exports a real `Worker` (engine mbjs-libc.c, compiled with USE_WORKER):
 * the constructor creates a new runtime + context in a worker entry point, wires
 * a message pipe pair, loads the named module there and runs its loop. Inside
 * the worker, `os.Worker.parent` is the pipe back to the parent, so
 * isMainThread is detected rather than hardcoded.
 *
 * Measured behaviour (selftest/mochi-worker.js): postMessage() from the parent
 * reaches the worker, the worker computes and posts back, and the parent's
 * 'message' handler receives it — fact(10) === 3628800.
 *
 * Honest limits:
 *   - postMessage(value) is delivered as msg.data === value (the engine wraps
 *     the posted value under a `data` property, which is what this shim reads).
 *   - Worker takes only the module filename. `options.workerData` is NOT
 *     delivered to the worker context (the engine passes a filename only);
 *     workerData is therefore null unless you relay it in the first message.
 *   - terminate() cannot be implemented: the engine exposes no worker handle
 *     to kill, so it resolves to 0 without stopping the worker.
 *   - threadId is null: the engine exposes no thread identifier.
 *   - No 'error' event: the worker's proto exposes only postMessage/onmessage.
 *   - MEASURED LIMITATION: once a Worker has been created the host process does
 *     not exit on its own (the worker's own runtime keeps the engine alive and
 *     no exit API is exposed to JS; MBJS_FreeRuntime is not exported). A
 *     selftest therefore reports its verdict by printing and relies on the
 *     harness applying `timeout`. selftest/mochi-worker.js documents this.
 */

import { EventEmitter } from '../mochievents/index.js';
import * as os from 'mbjs:os';

const parentObj = (os && os.Worker && os.Worker.parent) || null;

export const isMainThread = !parentObj;

class ParentPort extends EventEmitter {
    constructor(p) {
        super();
        this._p = p;
        p.onmessage = (msg) => this.emit('message', msg);
    }
    postMessage(value) { this._p.postMessage(value); return true; }
    get eventPort() { return this; }
}

export const parentPort = parentObj ? new ParentPort(parentObj) : null;
export const workerData = null;

export class Worker extends EventEmitter {
    constructor(filename, options) {
        super();
        if (typeof os.Worker !== 'function') {
            const err = new Error('mochiworker_threads: Worker unavailable on MochiBerry runtime');
            err.code = 'MOCHI_UNSUPPORTED';
            throw err;
        }
        this._w = new os.Worker(String(filename));
        this.threadId = null;
        this.resourceLimits = options && options.resourceLimits;
        this._w.onmessage = (msg) => this.emit('message', msg);
    }

    postMessage(value) { this._w.postMessage(value); }

    terminate() {
        /* Resolve on the next loop turn: awaiting a bare already-resolved promise
         * hangs here (the engine drives microtasks from timer/IO loop turns), so
         * schedule the resolution on a 0ms timer. */
        return new Promise((resolve) => { os.setTimeout(() => resolve(0), 0); });
    }

    unref() { return this; }
    ref() { return this; }
}

export function getResourceLimits() { return {}; }
export function markAsUntransferable() { return; }
export function isMarkedAsUntransferable() { return false; }
export function setResourceLimits() { return; }
export function receiveMessageOnPort() { return; }
export function moveMessagePortToContext() { return; }
export default { Worker, isMainThread, parentPort, workerData, getResourceLimits, setResourceLimits };
